{
  "1237": {
    "codebook_rule": ["1"],
    "document_id": "1237",
    "explanation": "Senator Harkin announces that Story County is receiving $249,950 from the DOJ's Justice and Mental Health Collaboration Program. The text explicitly states that Story County is receiving these funds, identifies the specific federal program, and links Senator Harkin's role as a senior member of the Senate Appropriations Committee to the announcement. This satisfies Rule 1 because it describes the senator obtaining/securing concrete funding for the county and presents him as responsible for the outcome. The classification is 1.",
    "label": "1"
  },
  "1886": {
    "codebook_rule": ["1", "2", "5"],
    "document_id": "1886",
    "explanation": "Senator Domenici announces that the Senate passed legislation he authored to protect the Fort Stanton Cave and its Snowy River Passage. The text states that Domenici 'penned' the legislation, identifies it as the 'Fort Stanton-Snowy River National Cave Conservation Act,' and announces its passage. This satisfies Rule 1 (personal responsibility for a concrete outcome), Rule 2 (legislative accomplishment achieved), and Rule 5 (connecting the named law to the senator as author). The classification is 1.",
    "label": "1"
  },
  "2740": {
    "codebook_rule": [],
    "document_id": "2740",
    "explanation": "Senator Feingold issued a statement supporting the President's veto of the WRDA bill. The text is a policy statement and does not describe a completed or secured outcome, nor does it claim that the senator obtained a benefit or produced a policy change. Therefore, it does not meet any of the rules and is classified as 0.",
    "label": "0"
  },
  "3879": {
    "codebook_rule": ["1"],
    "document_id": "3879",
    "explanation": "Senators Schumer and Clinton announced that $30 million was included in the Water Resources Development Act. The text explicitly attributes the outcome to the senators, stating that 'I will continue to fight for this funding' and 'The provision authorizes $30 million for these purposes.' This satisfies Rule 1 because it describes the senators obtaining/securing funding for the state and presents them as responsible for the outcome. The classification is 1.",
    "label": "1"
  },
  "4040": {
    "codebook_rule": ["1"],
    "document_id": "4040",
    "explanation": "Senator Harkin announced that Iowa will be receiving important funds to help combat gun crimes. The text states 'I am pleased that Iowa will be receiving these important funds,' which satisfies Rule 1 by claiming a concrete resource outcome for the state. The classification is 1.",
    "label": "1"
  },
  "4490": {
    "codebook_rule": ["1"],
    "document_id": "4490",
    "explanation": "Senator Alexander announced the passage of his Senate resolution celebrating Black History Month. The text states that the resolution passed the Senate unanimously and that Alexander 'penned' the legislation. This satisfies Rule 1 because it describes the senator obtaining/securing a legislative outcome and presents him as responsible for the outcome. The classification is 1.",
    "label": "1"
  },
  "4627": {
    "codebook_rule": ["1"],
    "document_id": "4627",
    "explanation": "Senator DeWine announced that the Coretta Scott King-Cesar Chavez Voting Rights Act Reauthorization passed 18-0 out of the Judiciary Committee. The text explicitly states that Senator DeWine is an original cosponsor of the bill and 'joined colleagues in support of' the bill. This satisfies Rule 1 because it describes the senator participating in a legislative accomplishment and presents him as responsible for the outcome. The classification is 1.",
    "label": "1"
  },
  "4735": {
    "codebook_rule": ["1"],
    "document_id": "4735",
    "explanation": "Senator Clinton announced that the new Navy Reserve Center to be built at the Schenectady County Airport is fully funded in the president's budget proposal. The text explicitly states that the center is fully funded and that Senator Clinton 'will work very hard to be sure that these funds remain in the FY 06 Budget.' This satisfies Rule 1 because it describes the senator obtaining/securing funding for the state and presents her as responsible for the outcome. The classification is 1.",
    "label": "1"
  },
  "4806": {
    "codebook_rule": [],
    "document_id": "4806",
    "explanation": "Senator Leahy announced that he granted an extension to the Bush Administration to respond to subpoenas regarding the warrantless wiretapping program. The text describes oversight activity and does not claim that the senator obtained a benefit or produced a policy change. Therefore, it does not meet any of the rules and is classified as 0.",
    "label": "0"
  },
  "614": {
    "codebook_rule": [],
    "document_id": "614",
    "explanation": "Senator Collins announced that she cosponsored the Access to Life-Saving Medicine Act. The text describes a bill being introduced and does not describe a completed or secured outcome, nor does it claim that the senator obtained a benefit or produced a policy change. Therefore, it does not meet any of the rules and is classified as 0.",
