  },
  "3408": {
    "codebook_rule": ["1", "4"],
    "document_id": "3408",
    "explanation": "The release announces USDA approval of more than $2.8 million in loans and grants for Peterborough water system upgrades. It presents the senator as announcing a concrete funding benefit for his state, satisfying rule 1 and rule 4. Although it does not explicitly say he obtained the funds, the announcement framing and identification of the benefit are sufficient under the codebook's funding/grant credit-claiming examples.",
    "label": "1"
  },
  "4449": {
    "codebook_rule": [],
    "document_id": "4449",
    "explanation": "The statement commemorates the September 11 anniversary and honors victims, first responders, and service members. It does not claim a concrete outcome, legislative success, award, funding, or intervention. It is commemorative and not credit-claiming.",
