  },
  "4466": {
    "codebook_rule": ["1", "4"],
    "document_id": "4466",
    "explanation": "The release encourages residents to apply for federal flood aid and includes the senator's statement that 'We have worked hard at the federal level to ensure that assistance is available.' This claims that the senator's advocacy helped make disaster assistance available, a concrete benefit for constituents, satisfying rules 1 and 4. The primary purpose is informational, but the explicit statement of having worked to ensure assistance is available is credit-claiming.",
    "label": "1"
  },
  "927": {
    "codebook_rule": ["2", "5"],
    "document_id": "927",
    "explanation": "The release announces that a Schumer-Clinton amendment has been included in the final House-Senate Conference report for the FY2006 Foreign Operations Appropriations Bill. It explicitly connects the amendment to the senators as their proposal and describes inclusion in a final legislative report, satisfying rule 2 and rule 5.",
    "label": "1"
  },
  "953": {
